export const ORCHARD_ROUTES=Object.fromEntries(habitats.map(([id,name,min,max,kind,DAY,NIGHT])=>[id,{name:(id.startsWith('pilgrim')?'Old Pilgrim Grove':id.startsWith('sunken')?'Sunken Shrine':'Orchard Way')+' · '+name,min,max,kind,DAY,NIGHT}]));
const roster=[
 ['TRN-C05-001','Orchard Keeper Muhammad ibn Abd Allah',['043','163','140'],[51,52,52],'First Light took the upper reservoir for its march. Our captain closed the lower gate in answer. Now both banks accuse the other while my trees burn. I still have partners fit to work. Let me see how you handle yours.','The ash reaches Cybressa by morning. They will call it distant trouble until the fruit wagons stop.'],
 ['TRN-C05-002','Pilgrim Aisha bint Abd Allah',['142','143','100'],[51,52,53],'My sister married across the river. A True Light priest blessed her door with almost the same words our shrine uses. The patrol at the bridge says that makes her a traitor. I am going to see her anyway.','People crossed the old procession path for births and weddings before anyone asked which prayer they spoke.'],
 ['TRN-C05-003','Shrine Guard Hasan ibn Abd Allah',['074','080','138'],[53,53,54],'The garrison has left. We stayed to carry water and keep the shrine doors open. Ismail will answer your challenge himself; these halls are a place to prepare, not a hidden army.','Go on. The mosaic names the channels that once fed the whole valley.'],
 ['TRN-C05-004','Hunter Husayn ibn Salim',['041','029','013'],[53,54,54],'The fire drove the nesting flocks into the old charcoal pits. Our patrol called them a plague and chased them back. You can guess what happened to the eggs. Keep your partners close in this smoke.','Some of the black trees are burning inside. Take the cleared road to Cossenne.'],
 ['TRN-C05-005','Grove Warden Zaynab bint Salim',['043','136','140'],[54,55,56],'They cut this grove for siege ladders. Our own officers marked the trunks, then blamed the western army when the pilgrims protested. I have kept the tally. No banner is going to tell me those stumps grew by themselves.','Read the final register. Decide what this spring should serve, then tell the attendant at the entrance.'],
 ['TRN-C05-006','Peacekeeper Yusuf ibn Salim',['132','100','143'],[55,56,56],'I have buried enough partners this season. This will be a supervised test: we stop before a lethal blow. If your officers ask why I refused a real fight, send them to me.','Keep that restraint when nobody is watching. Ismail sent his soldiers away so the families would not be caught between them.'],
 ['TRN-C05-007','Relic Keeper Asma bint Salim',['078','022','064','026'],[56,57,58,58],'Both armies want the shrine stones. One calls them proof of the Light; the other says the same carvings belong to the Bloom. Neither has offered to drain the room where the names of the dead are washing away.','The archive is yours to read. Winning a challenge does not make you the owner of the lives written here.'],
 ['TRN-C05-008','Veteran Musa ibn Khalid',['076','142','074','138'],[57,58,59,59],'Ismail ordered the garrison out before your column arrived. Some called it desertion. I watched him give their last cart to the injured. I stayed because somebody should remember which order came first.','He is in the inner garden. There is no army behind him. Hear him before you give yours an order.'],
 ['LDR-04','Warden Ismail ibn Umar',['043','142','143','140','163','136'],[55,56,57,58,59,60],'I sent the garrison away. You will find no siege here, and no villagers standing in front of my soldiers. I will face you myself. I will withdraw each partner at a quarter of its strength and send out the next. If all six are beaten, Cossenne is surrendered. Leave the orchards and the people out of our challenge.','My partners are beaten. Cossenne is yours. I surrender. There will be no second line of soldiers, no attack from the shrine.']
];
const team=(ids,levels,offset=0)=>ids.map((id,i)=>{const level=levels[i],species_id=legalForm(id,level);return {slot:i+offset+1,species_id,level,current_form_legal_move_ids:legalMoves(species_id,level)};});
export const COSSENNE_TRAINERS=roster.map(([id,name,ids,levels,before,after])=>({id,name,portraitId:id,faction:'Dawn Bloom',ai_tier:id==='LDR-04'?'Leader':['TRN-C05-007','TRN-C05-008'].includes(id)?'Leader-lite':'Advanced',role:id==='LDR-04'?'city leader':'Cossenne chapter',runtimeAuthored:true,nonlethal:id==='TRN-C05-006',team:team(ids,levels),before,after}));
// Later six-partner fort instruction: original source members retained in their original slots.
for(const [id,ids,levels]of [['TRN-C05-003',['061','163','136'],[53,54,54]],['TRN-C05-006',['043','140','136'],[55,56,56]],['TRN-C05-008',['136','140'],[58,59]]]){const t=COSSENNE_TRAINERS.find(t=>t.id===id);t.team.push(...team(ids,levels,t.team.length));t.teamExtension='Later user six-partner custodian rule';}
export function installCossenneTrainers(expansion,voices){for(const {before,after,...t}of COSSENNE_TRAINERS){if(!expansion.trainers.some(v=>v.id===t.id))expansion.trainers.push(t);if(voices)voices[t.id]={before,after,repeat:after};}}
export function orchardRoute(room){const r=ORCHARD_ROUTES[room];if(!r)return null;return {room,explorationTable:true,encounterPacing:true,area:{id:room,name:r.name,rate:'NORMAL'},tables:['DAY','NIGHT'].map(phase=>({id:room+'-'+phase,area_id:room,phase,slots:r[phase].map((id,i)=>{let min=r.min;while(min<=r.max&&legalForm(id,min)!==id)min++;if(min>r.max||!DATA.species.some(s=>s.id===id))throw Error('Illegal Orchard Way species '+id);return {species_id:id,min_level:min,max_level:r.max,weight:[35,28,22,10,5][i],authoredSlot:true,rarity:i<3?'Common':i===3?'Uncommon':'Rare'};})}))};}
export const COSSENNE_CACHES={'ow-west-cache':{heartyFood:3,poultices:2},'ow-firebreak-cache':{smoke:2,armedEscorts:1},'ow-renewal-cache':{poultices:3,emergencyEvacs:1},'ow-grove-cache':{trainingTonics:2},'ow-shrine-cache':{heartyFood:3,smoke:2}};

const sourceKits=[{"id":"TRN-C05-001","held_roles":"ace SUSTAIN","bag_uses":0},{"id":"TRN-C05-002","held_roles":"ace STATUS","bag_uses":0},{"id":"TRN-C05-003","held_roles":"ace GUARD","bag_uses":1},{"id":"TRN-C05-004","held_roles":"ace OFFENSE","bag_uses":0},{"id":"TRN-C05-005","held_roles":"ace SUSTAIN","bag_uses":0},{"id":"TRN-C05-006","held_roles":"ace STATUS","bag_uses":1},{"id":"TRN-C05-007","held_roles":"ace STATUS; slot2 GUARD","bag_uses":1},{"id":"TRN-C05-008","held_roles":"ace OFFENSE; slot2 SPEED","bag_uses":1},{"id":"LDR-04","bag_uses":1,"held_roles":"Olehart SUSTAIN; Regnacra HA+GUARD"}];
for(const t of COSSENNE_TRAINERS){const source=sourceKits.find(k=>k.id===t.id),original=roster.find(r=>r[0]===t.id);t.sourceHeldRoles=t.id==='LDR-04'?[{slot:1,role:'SUSTAIN'},{slot:6,role:'GUARD',hidden_ability:true}]:[{slot:original[2].length,role:source?.held_roles?.match(/ace ([A-Z]+)/)?.[1]}];const second=source?.held_roles?.match(/slot(\d+) ([A-Z]+)/);if(second)t.sourceHeldRoles.push({slot:Number(second[1]),role:second[2]});t.bagUses=source?.bag_uses||0;}
